        secondaryCertificateLink: OPTIONAL(CTX(9, IMPLICIT(CertificateLink))),
        primaryFP: OPTIONAL(CTX(10, IMPLICIT(OCTET_STRING))),
        secondaryFP: OPTIONAL(CTX(11, IMPLICIT(OCTET_STRING))),
